// merkle_builder.v — the commitment tree's inner vertices (blocks/tree/tree.h: a full
// binary tree over 2^log_n leaves; an inner vertex's value = vertex() of its two children,
// hash.h:482 = two_digests with index 0). vertex_hash: ONE blake2b_f call from
// begin64(tree_start, 32) over the block {tagword, index=0, left, right, 0...} with
// t_lo = 80, t_hi = 0, last = 1 (TREE_NODE = 166). merkle_builder: pairwise combining
// in place, log_n levels, root at slot 0.
// KATs: fpga/vectors/tree_kat.txt, generated by gen_tree_kat.cpp from hash.h itself.
`timescale 1ns/1ps
module vertex_hash (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         start,       // pulse with all inputs held
    input  wire [255:0] startw,      // the tree's start, 8 u32 (word i at [32*i +: 32])
    input  wire [255:0] left,        // left child digest, 8 u32
    input  wire [255:0] right,       // right child digest, 8 u32
    output reg          busy,
    output reg          done,        // one-cycle pulse; digest valid after it
    output reg  [255:0] digest       // 8 u32, narrow order
);
  function [63:0] iv_a(input integer i);
    case (i)
      0: iv_a = 64'h6a09e667f3bcc908; 1: iv_a = 64'hbb67ae8584caa73b;
      2: iv_a = 64'h3c6ef372fe94f82b; 3: iv_a = 64'ha54ff53a5f1d36f1;
      4: iv_a = 64'h510e527fade682d1; 5: iv_a = 64'h9b05688c2b3e6c1f;
      6: iv_a = 64'h1f83d9abfb41bd6b; default: iv_a = 64'h5be0cd19137e2179;
    endcase
  endfunction

  localparam [1:0] S_IDLE = 0, S_FWAIT = 1, S_NEXT = 2;

  reg  [1:0]   st;
  reg          f_start;
  reg  [511:0] f_hin;
  reg  [1023:0] f_min;
  wire         f_busy, f_done;
  wire [511:0] f_dout;

  blake2b_f fcore (
      .clk(clk), .rst_n(rst_n), .start(f_start),
      .hin(f_hin), .min(f_min), .t_lo(64'd80), .t_hi(64'd0), .last(1'b1),
      .busy(f_busy), .done(f_done), .dout(f_dout));

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      st <= S_IDLE; busy <= 1'b0; done <= 1'b0; f_start <= 1'b0;
    end else begin
      done <= 1'b0;
      f_start <= 1'b0;
      case (st)
        S_IDLE: if (start) begin
          // begin64 with DIGEST_BYTES = 32: h[0] ^= 0x01010020; h[4+i] ^= start 64-bit pair
          for (integer i = 0; i < 8; i = i + 1)
            f_hin[64*i +: 64] <= i == 0 ? iv_a(0) ^ 64'h0000000001010020
                              : (i < 4 ? iv_a(i) : iv_a(i) ^ startw[64*(i-4) +: 64]);
          // block: {tagword, index=0, left(4 u64), right(4 u64), 0 x6}; word k at [64k +: 64]
          f_min[63:0]     <= 64'd166;               // m64[0] = Domain::TREE_NODE
          f_min[127:64]   <= 64'd0;                 // m64[1] = index
          f_min[1023:640] <= 384'd0;                // m64[10..15]
          for (integer j = 0; j < 4; j = j + 1) begin
            f_min[64*(2+j) +: 64] <= left[64*j +: 64];
            f_min[64*(6+j) +: 64] <= right[64*j +: 64];
          end
          f_start <= 1'b1;
          busy <= 1'b1;
          st <= S_FWAIT;
        end
        S_FWAIT: if (f_done) begin
          st <= S_NEXT;
        end
        S_NEXT: begin
          for (integer i = 0; i < 4; i = i + 1) digest[64*i +: 64] <= f_dout[64*i +: 64];
          done <= 1'b1; busy <= 1'b0; st <= S_IDLE;
        end
        default: st <= S_IDLE;
      endcase
    end
  end
endmodule

module merkle_builder #(
    parameter integer NLEAF_LOG2 = 3        // 2^NLEAF_LOG2 leaves, power of two
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         load_en,         // leaf write port
    input  wire [31:0]  load_addr,       // leaf index 0 .. 2^NLEAF_LOG2-1
    input  wire [255:0] load_data,
    input  wire [255:0] startw,          // the tree's start
    input  wire         start,
    output reg          busy,
    output reg          done,            // one-cycle pulse; root valid after it
    output wire [255:0] root             // digest at slot 0
);
  localparam [2:0] S_IDLE = 0, S_READ = 1, S_HASH = 2, S_WRITE = 3, S_LEVEL = 4, S_DONE = 5;

  reg [255:0] ram [0:(1 << NLEAF_LOG2) - 1];
  reg [31:0]  n;                          // digests at the current level
  reg [31:0]  i;                          // pair index within the level
  reg [2:0]   st;
  reg         vh_start;
  reg [255:0] vh_left, vh_right;
  wire        vh_busy, vh_done;
  wire [255:0] vh_digest;

  vertex_hash vh (
      .clk(clk), .rst_n(rst_n), .start(vh_start), .startw(startw),
      .left(vh_left), .right(vh_right),
      .busy(vh_busy), .done(vh_done), .digest(vh_digest));

  assign root = ram[0];

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      st <= S_IDLE; busy <= 1'b0; done <= 1'b0; vh_start <= 1'b0;
      n <= 32'd0; i <= 32'd0;
    end else begin
      done <= 1'b0;
      vh_start <= 1'b0;
      if (load_en) ram[load_addr] <= load_data;
      case (st)
        S_IDLE: if (start) begin
          n <= 32'd1 << NLEAF_LOG2; i <= 32'd0; busy <= 1'b1; st <= S_READ;
        end
        S_READ: begin
          vh_left <= ram[2 * i];
          vh_right <= ram[2 * i + 1];
          vh_start <= 1'b1;
          st <= S_HASH;
        end
        S_HASH: if (vh_done) begin
          ram[i] <= vh_digest;             // in place: slot i < 2i for i >= 1; slot 0 read first
          i <= i + 32'd1;
          st <= S_WRITE;
        end
        S_WRITE: begin
          if (2 * i >= n) begin            // this level's pairs exhausted
            n <= n >> 1; i <= 32'd0;
            st <= S_LEVEL;
          end else begin
            st <= S_READ;
          end
        end
        S_LEVEL: begin
          if (n == 32'd1) begin
            done <= 1'b1; busy <= 1'b0; st <= S_IDLE;
          end else begin
            st <= S_READ;
          end
        end
        default: st <= S_IDLE;
      endcase
    end
  end
endmodule
